export type MugrationOutputSelection = 'All' | 'Nwk' | 'Nexus' | 'Auspice' | 'MatPb' | 'MatJson' | 'GraphJson' | 'Dot' | 'AugurNodeData' | 'Gtr' | 'ConfidenceCsv' | 'TraitsCsv';

/**
 * Metadata identity and delimiter options shared by every command that reads a metadata table
 * (`timetree`, `clock`, `mugration`).
 *
 * `--metadata-id-columns` (alias `--name-column`) lists the candidate columns holding the taxon
 * identifier that links a metadata row to a tree tip; the first column present in the header wins.
 * Matching is case-insensitive (see `treetime-io` column detection). `--metadata-delimiters` lists
 * candidate field separators; the delimiter actually present in the file is used.
 */
export type MugrationConfig = {
  /**
   * Tree in Newick format.
   */
  tree?: string | null;
  /**
   * Attribute to reconstruct, e.g. country
   */
  attribute?: string | null;
  /**
   * CSV or TSV file with discrete characters. #name,country,continent taxon1,micronesia,oceania ...
   */
  metadata?: string | null;
  /**
   * CSV or TSV file with probabilities of that a randomly sampled sequence at equilibrium has a particular state. E.g. population of different continents or countries. E.g.: #country,weight micronesia,0.1 ...
   */
  weights?: string | null;
  /**
   * Candidate column name(s) holding the taxon identifier that links metadata to tree tips
   *
   * The first listed column that is present in the header is used. Matching is case-insensitive.
   */
  metadata_id_columns?: Array<string>;
  /**
   * Candidate field delimiter(s) for the metadata table
   *
   * The delimiter actually present in the file is used. Defaults to comma, tab, and semicolon.
   */
  metadata_delimiters?: Array<string>;
  /**
   * Path to output state-probability-profile CSV.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   */
  output_confidence_csv?: string | null;
  /**
   * Pseudo-counts. Higher numbers results in 'flatter' models. Default: 1.0.
   */
  pc?: number | null;
  /**
   * String indicating missing data
   */
  missing_data?: string;
  /**
   * Portion of attribute values that is allowed to not have weights in the weights file
   */
  missing_weights_threshold?: number;
  /**
   * Number of iterations for GTR model refinement from data.
   */
  iterations?: number;
  /**
   * Rough estimate of how many more events would have been observed if sequences represented an
   * even sample.
   */
  sampling_bias_correction?: number | null;
  /**
   * Smooth the initial equilibrium frequencies with the pseudo-count before the first
   * reconstruction pass.
   *
   * Off by default (TreeTime v0 builds the initial model from raw frequencies and applies the
   * pseudo-count only as infer_gtr regularization). Enabling this flattens the prior for the first
   * pass; it only affects weighted models.
   */
  smooth_initial_pi?: boolean;
  /**
   * Exclude near-uniform root positions from the equilibrium-frequency prior.
   *
   * Off by default (TreeTime v0 always folds the root's most-likely state into the prior). Enabling
   * this drops root positions whose posterior carries no phylogenetic signal, removing a
   * state-order-dependent bias at ambiguous roots.
   */
  filter_uninformative_root?: boolean;
  /**
   * Path to output augur-compatible node data JSON.
   *
   * Contains per-node discrete trait assignments, confidence profiles, entropy,
   * the inferred substitution model, and branch state-change labels. The output
   * is compatible with augur export v2 --node-data for Nextstrain pipeline
   * integration.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   */
  output_augur_node_data?: string | null;
  /**
   * Path to output GTR model JSON.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   */
  output_gtr?: string | null;
  /**
   * Path to output traits CSV.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   */
  output_traits_csv?: string | null;
  /**
   * Random seed
   */
  seed?: number | null;
  /**
   * Write all default output files into this directory.
   *
   * Produces the default set of tree and non-tree outputs for the command, using
   * `<dir>/<command>.<ext>` paths. Combine with `--output-selection` to restrict which
   * outputs are written.
   *
   * Per-file flags (`--output-tree-nwk`, `--output-augur-node-data`, etc.) override or
   * supplement the files produced by `--output-all`.
   */
  output_all?: string | null;
  /**
   * NWK/Nexus annotation styles to write (comma-separated): `plain`, `beast`, `nhx`.
   *
   * Applies to every NWK and Nexus output. With more than one style, files are distinguished by a
   * secondary extension (`.annotated` for beast, `.nhx` for nhx). Default: `plain`.
   */
  output_nwk_style?: Array<NwkStyleArg>;
  /**
   * Path to output Newick tree file.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`. With
   * multiple `--output-nwk-style` values, a secondary extension is inserted per style.
   *
   * Compression: path ending in `.gz`, `.bz2`, `.xz`, `.zst` writes compressed output.
   * Use `-` to write uncompressed to stdout.
   *
   * Parent directories are created if missing.
   */
  output_tree_nwk?: string | null;
  /**
   * Path to output Nexus tree file.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`. With
   * multiple `--output-nwk-style` values, a secondary extension is inserted per style.
   *
   * Compression: path ending in `.gz`, `.bz2`, `.xz`, `.zst` writes compressed output.
   * Use `-` to write uncompressed to stdout.
   *
   * Parent directories are created if missing.
   */
  output_tree_nexus?: string | null;
  /**
   * Path to output Auspice v2 JSON tree file.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   *
   * Compression: path ending in `.gz`, `.bz2`, `.xz`, `.zst` writes compressed output.
   * Use `-` to write uncompressed to stdout.
   *
   * Parent directories are created if missing.
   */
  output_tree_auspice?: string | null;
  /**
   * Path to output UShER MAT protobuf tree file.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   *
   * Compression: path ending in `.gz`, `.bz2`, `.xz`, `.zst` writes compressed output.
   * Use `-` to write uncompressed to stdout.
   *
   * Parent directories are created if missing.
   */
  output_tree_mat_pb?: string | null;
  /**
   * Path to output UShER MAT JSON tree file.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   *
   * Compression: path ending in `.gz`, `.bz2`, `.xz`, `.zst` writes compressed output.
   * Use `-` to write uncompressed to stdout.
   *
   * Parent directories are created if missing.
   */
  output_tree_mat_json?: string | null;
  /**
   * Path to output internal graph JSON tree file.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   *
   * Compression: path ending in `.gz`, `.bz2`, `.xz`, `.zst` writes compressed output.
   * Use `-` to write uncompressed to stdout.
   *
   * Parent directories are created if missing.
   */
  output_tree_graph_json?: string | null;
  /**
   * Path to output Graphviz DOT tree file.
   *
   * Takes precedence over paths configured with `--output-all` and `--output-selection`.
   *
   * Compression: path ending in `.gz`, `.bz2`, `.xz`, `.zst` writes compressed output.
   * Use `-` to write uncompressed to stdout.
   *
   * Parent directories are created if missing.
   */
  output_tree_dot?: string | null;
  /**
   * Comma-separated list of outputs to produce with `--output-all`.
   *
   * Restricts which outputs `--output-all` writes. Special value `all` expands to every output
   * available for this command. Requires `--output-all`. Per-file flags are always honored
   * regardless of this selection.
   */
  output_selection?: Array<MugrationOutputSelection>;
  /**
   * Order tree topology before writing output files.
   */
  ladderize?: LadderizeArg | null;
  /**
   * Canonical topology ordering preset.
   */
  topology_order?: TopologyOrderArg | null;
  /**
   * Source for target-order topology sorting.
   */
  topology_order_target_source?: TopologyOrderTargetSourceArg | null;
  /**
   * File used by list or reference-topology target-order sources.
   */
  topology_order_target_file?: string | null;
  /**
   * Aggregate used to map a subtree to a target-order position.
   */
  topology_order_target_aggregate?: TopologyOrderTargetAggregateArg;
  /**
   * Path or URL of the JSON schema for this config; used by editors and ignored by the loader.
   */
  $schema?: string;
};

/**
 * Event of a running job, in the order the job emits them.
 */
export type JobEvent = ({
  type: 'started';
} & JobEventStarted) | ({
  type: 'progress';
} & JobEventProgress) | ({
  type: 'log';
} & JobEventLog) | ({
  type: 'iteration';
} & JobEventIteration) | ({
  type: 'terminal';
} & JobEventTerminal);

/**
 * Settings of one command.
 */
export type CommandSettings = {
  /**
   * The command.
   */
  command: AppCommand;
  /**
   * Input files the command reads, in the order the form asks for them.
   */
  inputs: Array<InputSlot>;
  /**
   * Whether the command reads sampling dates from the metadata.
   */
  uses_dates: boolean;
  /**
   * Setting groups, in the order `treetime <command> --help` lists their headings.
   */
  groups: Array<string>;
  /**
   * Every setting of the command, by group, in the order `--help` lists them.
   */
  settings: Array<SettingSpec>;
};

/**
 * An input file of a command, as the form asks for it.
 */
export type InputSlot = {
  /**
   * Kind of the file; also the setting that names it.
   */
  kind: InputKind;
  /**
   * Whether a run of the app needs the file.
   */
  need: InputNeed;
  /**
   * Name of the input, for example `Tree`.
   */
  label: string;
  /**
   * File formats the readers accept, for example `Newick`.
   */
  formats: string;
  /**
   * File name extensions of the accepted formats, compressed forms included, without the dot.
   */
  extensions: Array<string>;
  /**
   * Whether the setting takes a list of files.
   */
  list: boolean;
};

/**
 * How much a run of the app needs an input file.
 */
export type InputNeed = 'required' | 'recommended' | 'optional';

/**
 * One setting of a command.
 */
export type SettingSpec = {
  /**
   * Key path of the setting joined with `.`, for example `branch_split.method`.
   */
  key: string;
  /**
   * Key path of the setting in the configuration.
   */
  path: Array<string>;
  /**
   * Name of the setting as the form shows it, for example `Clock rate std. dev.`.
   */
  label: string;
  /**
   * Command-line flag, for example `--clock-rate`.
   */
  flag: string;
  /**
   * Heading of the setting in `--help`.
   */
  group: string;
  /**
   * What the setting names: a file, or a value.
   */
  role: SettingRole;
  /**
   * Form of the value, which selects the control that edits it.
   */
  kind: SettingKind;
  /**
   * Whether the setting can be unset.
   */
  nullable: boolean;
  /**
   * Allowed values of an `enum` or `enum-list` setting.
   */
  options: Array<SettingOption>;
  /**
   * Type of the items of a `list` setting.
   */
  item_kind: ListItemKind;
  /**
   * Value of the setting when the configuration does not set it.
   */
  default_value: unknown;
  /**
   * Smallest allowed value of a number, when there is one.
   */
  minimum?: number | null;
  /**
   * Typical values of the setting, as the configuration spells them; the first one is the value the form fills in
   * when the setting is turned on.
   */
  examples: Array<unknown>;
  /**
   * Names of the values the command-line flag takes, in order, for example `SLACK` and `COUPLING`.
   */
  value_names: Array<string>;
  /**
   * Keys of the settings this setting cannot be used together with, as the command line rejects them.
   */
  conflicts: Array<string>;
  /**
   * First paragraph of the setting's description.
   */
  help: string;
  /**
   * Remaining paragraphs of the setting's description.
   */
  more: string;
};

/**
 * What a setting names.
 */
export type SettingRole = 'setting' | 'input' | 'input-template' | 'output';

/**
 * Form of a setting's value.
 */
export type SettingKind = 'switch' | 'tristate' | 'enum' | 'integer' | 'number' | 'text' | 'list' | 'enum-list';

/**
 * One allowed value of a setting.
 */
export type SettingOption = {
  /**
   * The value, as the configuration spells it.
   */
  value: string;
  /**
   * Description of the value, when it has one.
   */
  help: string;
};

/**
 * Type of the items of a list setting.
 */
export type ListItemKind = 'string' | 'number' | 'integer';

/**
 * Settings of every command the app runs, as the settings form shows them.
 */
export type SettingCatalog = {
  /**
   * Settings of each command.
   */
  commands: Array<CommandSettings>;
};

/**
 * The configuration is accepted.
 */
export type CheckConfigResponseValid = {
  /**
   * Command the configuration is for.
   */
  command: AppCommand;
  /**
   * The configuration with every default filled in.
   */
  config: {
    [key: string]: unknown;
  };
  /**
   * The command line and the YAML config that reproduce the configuration.
   */
  code: ConfigCode;
  /**
   * Findings about the configuration and its input files.
   */
  checks: Array<RunCheck>;
  status: 'valid';
};

/**
 * The configuration is rejected.
 */
export type CheckConfigResponseInvalid = {
  /**
   * Command the configuration is for.
   */
  command: AppCommand;
  /**
   * The error, as the CLI prints it.
   */
  message: string;
  /**
   * The errors that caused `message`, outermost first.
   */
  causes: Array<string>;
  /**
   * Problems found by parsing and by the schema check, empty for other errors.
   */
  problems: Array<ConfigProblem>;
  /**
   * The problems drawn against the configuration text, when the text could be parsed.
   */
  rendered?: string | null;
  /**
   * The problems as a user reads them: each parse and schema problem with its help, or the error and its causes.
   */
  messages: Array<string>;
  /**
   * Findings about the configuration and its input files; the rejection is among them.
   */
  checks: Array<RunCheck>;
  status: 'invalid';
};

/**
 * The configuration is accepted.
 */
export type RunConfigResponseValid = {
  /**
   * The configuration as the run records it, with every default filled in, the outputs the run layer adds, and
   * `output_all` set to `out`.
   */
  config: {
    [key: string]: unknown;
  };
  /**
   * The command line and the YAML config that reproduce the run.
   */
  code: ConfigCode;
  /**
   * Hash that a run of this configuration records, to find finished runs with the same settings and input
   * contents; absent when an input cannot be read.
   */
  config_hash?: string | null;
  /**
   * Why `config_hash` is absent.
   */
  config_hash_error?: string | null;
  status: 'valid';
};

/**
 * The configuration is rejected.
 */
export type RunConfigResponseInvalid = {
  /**
   * The error, as the CLI prints it.
   */
  message: string;
  /**
   * The errors that caused `message`, outermost first.
   */
  causes: Array<string>;
  /**
   * Problems found by parsing and by the schema check, empty for other errors.
   */
  problems: Array<ConfigProblem>;
  status: 'invalid';
};

export type CommandResultsTimetree = {
  command: 'timetree';
  data: TimetreeResults;
};

export type CommandResultsClock = {
  command: 'clock';
  data: ClockResults;
};

export type CommandResultsAncestral = {
  command: 'ancestral';
  data: AncestralResults;
};

export type CommandResultsMugration = {
  command: 'mugration';
  data: MugrationResults;
};

export type CommandResultsOptimize = {
  command: 'optimize';
  data: TreeSummary;
};

export type CommandResultsPrune = {
  command: 'prune';
  data: TreeSummary;
};

/**
 * No coalescent prior.
 */
export type CoalescentPriorNone = {
  kind: 'none';
};

/**
 * Constant population size with a fixed time scale.
 */
export type CoalescentPriorFixed = {
  /**
   * Coalescent time scale in years.
   */
  tc: number;
  kind: 'fixed';
};

/**
 * Constant population size with an optimized time scale.
 */
export type CoalescentPriorOptimized = {
  kind: 'optimized';
};

/**
 * Piecewise-constant population size.
 */
export type CoalescentPriorSkyline = {
  /**
   * Number of grid points.
   */
  points: number;
  /**
   * Stiffness of the skyline.
   */
  stiffness: number;
  kind: 'skyline';
};

/**
 * A value that controls the analysis.
 */
export type SettingDifferenceSetting = {
  /**
   * Key path of the setting joined with `.`.
   */
  key: string;
  /**
   * Value in the first run.
   */
  first: unknown;
  /**
   * Value in the second run.
   */
  second: unknown;
  kind: 'setting';
};

/**
 * Input files, which differ in their paths, their contents, or both.
 */
export type SettingDifferenceInput = {
  /**
   * Key path of the setting that names the files.
   */
  key: string;
  /**
   * Paths of the files the first run read.
   */
  first: Array<string>;
  /**
   * Paths of the files the second run read.
   */
  second: Array<string>;
  /**
   * Whether the files of both runs have the same contents.
   */
  same_content: boolean;
  kind: 'input';
};

/**
 * The job was accepted; always the first event.
 */
export type RunEventStarted = {
  /**
   * Position of the event in the run's event stream, starting at 0. Subscribing from `seq + 1` resumes after it.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  type: 'started';
  data: JobStarted;
};

/**
 * A stage of the computation began or advanced.
 */
export type RunEventProgress = {
  /**
   * Position of the event in the run's event stream, starting at 0. Subscribing from `seq + 1` resumes after it.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  type: 'progress';
  data: ProgressEvent;
};

/**
 * A diagnostic message of the computation.
 */
export type RunEventLog = {
  /**
   * Position of the event in the run's event stream, starting at 0. Subscribing from `seq + 1` resumes after it.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  type: 'log';
  data: LogEvent;
};

/**
 * Convergence values of one timetree optimization iteration.
 */
export type RunEventIteration = {
  /**
   * Position of the event in the run's event stream, starting at 0. Subscribing from `seq + 1` resumes after it.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  type: 'iteration';
  data: IterationEvent;
};

/**
 * The job ended; always the last event, exactly once per job.
 */
export type RunEventTerminal = {
  /**
   * Position of the event in the run's event stream, starting at 0. Subscribing from `seq + 1` resumes after it.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  type: 'terminal';
  data: TerminalEvent;
};

/**
 * The command ran to completion.
 */
export type TerminalEventOk = {
  job_id: JobId;
  result: CommandOutcome;
  status: 'ok';
};

/**
 * The command failed, or its configuration was rejected.
 */
export type TerminalEventError = {
  job_id: JobId;
  /**
   * The error, as the CLI prints it.
   */
  message: string;
  /**
   * The errors that caused `message`, outermost first.
   */
  causes: Array<string>;
  status: 'error';
};

/**
 * The job stopped because cancellation was requested.
 */
export type TerminalEventCancelled = {
  job_id: JobId;
  status: 'cancelled';
};

/**
 * The job stopped because the process that ran it stopped.
 */
export type TerminalEventInterrupted = {
  job_id: JobId;
  status: 'interrupted';
};

/**
 * A run was created.
 */
export type AppEventRunCreated = {
  /**
   * Position of the event in the app-wide event stream. Each event has the number of the previous one plus 1, and a
   * restarted server numbers its events above those of the previous server. Subscribing from `seq + 1` resumes after
   * the event.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  /**
   * REST paths whose answers the change made stale.
   */
  stale: Array<StalePath>;
  /**
   * The new run.
   */
  run: RunSummary;
  kind: 'run-created';
};

/**
 * A run changed: it started, ended, or got a new title or pinned state.
 */
export type AppEventRunUpdated = {
  /**
   * Position of the event in the app-wide event stream. Each event has the number of the previous one plus 1, and a
   * restarted server numbers its events above those of the previous server. Subscribing from `seq + 1` resumes after
   * the event.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  /**
   * REST paths whose answers the change made stale.
   */
  stale: Array<StalePath>;
  /**
   * The run after the change.
   */
  run: RunSummary;
  kind: 'run-updated';
};

/**
 * A run moved to the trash.
 */
export type AppEventRunDeleted = {
  /**
   * Position of the event in the app-wide event stream. Each event has the number of the previous one plus 1, and a
   * restarted server numbers its events above those of the previous server. Subscribing from `seq + 1` resumes after
   * the event.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  /**
   * REST paths whose answers the change made stale.
   */
  stale: Array<StalePath>;
  /**
   * Id of the run.
   */
  id: JobId;
  kind: 'run-deleted';
};

/**
 * A run came back from the trash.
 */
export type AppEventRunRestored = {
  /**
   * Position of the event in the app-wide event stream. Each event has the number of the previous one plus 1, and a
   * restarted server numbers its events above those of the previous server. Subscribing from `seq + 1` resumes after
   * the event.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  /**
   * REST paths whose answers the change made stale.
   */
  stale: Array<StalePath>;
  /**
   * The restored run.
   */
  run: RunSummary;
  kind: 'run-restored';
};

/**
 * A deleted run was removed for good.
 */
export type AppEventRunPurged = {
  /**
   * Position of the event in the app-wide event stream. Each event has the number of the previous one plus 1, and a
   * restarted server numbers its events above those of the previous server. Subscribing from `seq + 1` resumes after
   * the event.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  /**
   * REST paths whose answers the change made stale.
   */
  stale: Array<StalePath>;
  /**
   * Id of the run.
   */
  id: JobId;
  kind: 'run-purged';
};

/**
 * The stream cannot continue after the requested event, because the server no longer keeps that event or the
 * event belongs to a previous server. Every path in `stale` must be read again; the stream continues with the
 * events after this one.
 */
export type AppEventResync = {
  /**
   * Position of the event in the app-wide event stream. Each event has the number of the previous one plus 1, and a
   * restarted server numbers its events above those of the previous server. Subscribing from `seq + 1` resumes after
   * the event.
   */
  seq: number;
  /**
   * Time the event was recorded.
   */
  time: string;
  /**
   * REST paths whose answers the change made stale.
   */
  stale: Array<StalePath>;
  kind: 'resync';
};

/**
 * The job was accepted; always the first event.
 */
export type JobEventStarted = {
  type: 'started';
  data: JobStarted;
};

/**
 * A stage of the computation began or advanced.
 */
export type JobEventProgress = {
  type: 'progress';
  data: ProgressEvent;
};

/**
 * A diagnostic message of the computation.
 */
export type JobEventLog = {
  type: 'log';
  data: LogEvent;
};

/**
 * Convergence values of one timetree optimization iteration.
 */
export type JobEventIteration = {
  type: 'iteration';
  data: IterationEvent;
};

/**
 * The job ended; always the last event, exactly once per job.
 */
export type JobEventTerminal = {
  type: 'terminal';
  data: TerminalEvent;
};

